package com.example.kotlinPractice.codingRound

fun isPrime(num: Int): Boolean {
    if (num <= 1)
        return false
    for (i in 2 until num)
    {
        if (num % i == 0)
            return false
    }
    return true
}

fun main() {
    for (i in 1.rangeTo(99)) {
        if (isPrime(i)) {
            println(i)
        }
    }
}
